<?php
require_once "inc/config.php"; require_once "inc/admin_auth.php"; require_admin_permission($pdo,'subscriptions');
$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$where=[];$p=[];if(in_array($status,['pending','active','past_due','canceled','expired'],true)){$where[]='s.status=?';$p[]=$status;}if($q!==''){$where[]='(CAST(s.id AS CHAR)=? OR c.full_name LIKE ? OR p.name LIKE ?)';$like="%$q%";array_push($p,$q,$like,$like);}
$sql="SELECT s.id,s.cust_id,s.package_id,s.status,s.starts_at,s.ends_at,s.price_paid,s.currency,s.auto_renew,c.full_name,p.name package_name FROM customer_subs s JOIN customers c ON c.id=s.cust_id LEFT JOIN packages p ON p.id=s.package_id";if($where)$sql.=" WHERE ".implode(' AND ',$where);$sql.=" ORDER BY s.id DESC LIMIT 100";$stmt=$pdo->prepare($sql);$stmt->execute($p);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="az"><head><?php include "inc/head.php"; ?></head><body><div class="app-main"><div id="app-wrapper" class="app-wrapper d-flex flex-column align-items-stretch min-vh-100"><?php include "inc/sidebar.php"; ?><?php include "inc/navbar.php"; ?><div class="app-content-wrapper py-13"><div class="container-fluid"><div class="page-header pb-7 d-flex justify-content-between align-items-center"><div><h2 class="fw-semibold fs-7">Abunəliklər</h2><div class="text-muted">Aktiv, bitmiş və ləğv edilmiş abunəliklərin tarixçəsi.</div></div><a class="btn btn-outline-primary" href="api/management/export.php?type=subscriptions">CSV export</a></div><form class="row g-3 mb-5"><div class="col-md-5"><input class="form-control" name="q" value="<?=admin_h($q)?>" placeholder="Abunəlik ID, vendor, paket"></div><div class="col-md-5"><select class="form-control" name="status"><option value="">Bütün statuslar</option><?php foreach(['pending','active','past_due','canceled','expired'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtr</button></div></form><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body table-responsive"><table class="table"><tr><th>ID</th><th>Vendor</th><th>Paket</th><th>Status</th><th>Müddət</th><th>Məbləğ</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=admin_h($r['full_name'])?></td><td><?=admin_h($r['package_name']??'-')?></td><td><?=admin_h($r['status'])?></td><td><?=admin_h($r['starts_at'])?> → <?=admin_h($r['ends_at'])?></td><td><?=admin_h($r['price_paid'].' '.$r['currency'])?></td></tr><?php endforeach;?></table></div></div></div></div><?php include "inc/footer.php"; ?></div></div><?php include "inc/scripts_url.php"; ?></body></html>
